export interface AmebaChatMessage {
  role: 'user' | 'assistant' | 'system';
  content: string;
}

export interface WebSource {
  title: string;
  url: string;
  snippet?: string;
}

export interface StreamUpdate {
  content: string;
  reasoningContent?: string;
  isThinking?: boolean;
  thinkingTimeSeconds?: number;
  sources?: WebSource[];
}

/**
 * NATIVE SSE STREAMING FROM NEURAL NETWORK (DEEPSEEK R1 PATTERN)
 * Streams reasoning_content & content token-by-token directly as generated by LLM
 */
export async function sendChatMessageToAmeba(
  messages: AmebaChatMessage[],
  options: {
    systemPrompt?: string;
    model?: string;
    webSearch?: boolean;
    thinkingMode?: boolean;
    onUpdate?: (update: StreamUpdate) => void;
    signal?: AbortSignal;
  }
): Promise<{ content: string; reasoningContent?: string; sources?: WebSource[] }> {
  const {
    systemPrompt,
    model = 'ameba-1.2-flash',
    webSearch = false,
    thinkingMode = true,
    onUpdate,
    signal
  } = options;

  const preparedMessages: AmebaChatMessage[] = [];

  if (systemPrompt && systemPrompt.trim()) {
    preparedMessages.push({
      role: 'system',
      content: systemPrompt.trim(),
    });
  }

  // Include recent conversation messages (up to 20 for context)
  const recent = messages.slice(-20);
  preparedMessages.push(...recent);

  const startTime = Date.now();
  const res = await fetch('/api/chat', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      messages: preparedMessages,
      model,
      stream: true, // Native live SSE streaming from LLM
      webSearch,
      thinkingMode,
    }),
    signal,
  });

  if (!res.ok) {
    const errData = await res.json().catch(() => ({}));
    throw new Error(errData.detail || errData.error || `HTTP error ${res.status}`);
  }

  if (!res.body) {
    throw new Error('ReadableStream not supported by client environment');
  }

  const reader = res.body.getReader();
  const decoder = new TextDecoder('utf-8');

  let fullContent = '';
  let fullReasoning = '';
  let sources: WebSource[] = [];
  let isThinking = thinkingMode;
  let inThinkTag = false;
  let buffer = '';

  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split('\n');
      buffer = lines.pop() || '';

      for (const line of lines) {
        const trimmed = line.trim();
        if (!trimmed || trimmed.startsWith(':')) continue;
        if (trimmed === 'data: [DONE]') break;

        if (trimmed.startsWith('data: ')) {
          const jsonStr = trimmed.slice(6);
          try {
            const parsed = JSON.parse(jsonStr);

            // Check if search sources metadata chunk
            if (parsed.sources) {
              sources = parsed.sources;
              continue;
            }

            const delta = parsed.choices?.[0]?.delta;
            if (!delta) continue;

            // 1. Native DeepSeek R1 reasoning_content stream field
            if (delta.reasoning_content) {
              fullReasoning += delta.reasoning_content;
              isThinking = true;
            }

            // 2. Native DeepSeek R1 <think> ... </think> tag stream
            if (delta.content) {
              const chunkText = delta.content;

              if (chunkText.includes('<think>')) {
                inThinkTag = true;
                isThinking = true;
                const parts = chunkText.split('<think>');
                if (parts[0]) fullContent += parts[0];
                if (parts[1]) fullReasoning += parts[1];
              } else if (chunkText.includes('</think>')) {
                inThinkTag = false;
                isThinking = false;
                const parts = chunkText.split('</think>');
                if (parts[0]) fullReasoning += parts[0];
                if (parts[1]) fullContent += parts[1];
              } else if (inThinkTag) {
                fullReasoning += chunkText;
                isThinking = true;
              } else {
                fullContent += chunkText;
                if (!delta.reasoning_content) {
                  isThinking = false;
                }
              }
            }

            const elapsedSec = Math.max(1, Math.round((Date.now() - startTime) / 1000));

            if (onUpdate) {
              onUpdate({
                content: fullContent,
                reasoningContent: fullReasoning,
                isThinking,
                thinkingTimeSeconds: elapsedSec,
                sources,
              });
            }
          } catch {
            // Ignore incomplete JSON chunks in SSE stream
          }
        }
      }
    }
  } catch (err) {
    if (signal?.aborted) {
      throw new Error('Generation stopped by user');
    }
    throw err;
  }

  return {
    content: fullContent,
    reasoningContent: fullReasoning,
    sources,
  };
}
